export function Widget({
  title = "{{title}}",
  body = "{{body}}",
  variant = "{{variant}}",
  accent = "{{accent}}",
  showAction = {{showAction}},
  radius = {{radius}},
}) {
  const minimal = variant === "minimal";
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 15, lineHeight: 1.5, color: "#241430",
      background: "#FAF7F2", boxSizing: "border-box", maxWidth: 300, overflow: "hidden", borderRadius: radius,
      border: minimal ? "1.5px solid #24143025" : "none",
      boxShadow: minimal ? "none" : "0 12px 28px rgba(36,20,48,.14)" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8,
        padding: "14px 16px", borderBottom: minimal ? "none" : "1px solid #24143015" }}>
        <h4 style={{ margin: 0, fontSize: 14, fontWeight: 700 }}>{title}</h4>
        {showAction && (
          <button type="button" aria-label="Refresh" style={{ width: 26, height: 26, borderRadius: "50%",
            border: `1.5px solid ${accent}`, background: "transparent", color: accent, cursor: "pointer",
            fontSize: 14, lineHeight: 1 }}>⟳</button>
        )}
      </div>
      <div style={{ padding: "14px 16px" }}>
        <p style={{ margin: 0, fontSize: 13.5, color: "#241430b3" }}>{body}</p>
      </div>
    </div>
  );
}
